import{z as E,x as p,o,c as d,q as i,j as m,D as e,d as t,s,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"LayerNorm 的动机","description":"","frontmatter":{"title":"LayerNorm 的动机","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/why-layernorm.md","filePath":"llm/why-layernorm.md","lastUpdated":1791413859000}'),B={name:"llm/why-layernorm.md"};function h(N,a,A,f,L,u){const l=p("Mermaid");return o(),d("div",null,[a[2]||(a[2]=i('<h1 id="layernorm-的动机" tabindex="-1">LayerNorm 的动机 <a class="header-anchor" href="#layernorm-的动机" aria-label="Permalink to &quot;LayerNorm 的动机&quot;">​</a></h1><div class="epigraph"><p>残差保证有路可走，不保证路上的向量尺度稳定；按特征维减均值除标准差，把每个位置重新放到可比的量级。</p><footer>—— 据 Ba, Kiros &amp; Hinton, Layer Normalization, 2016 整理</footer></div><p><a href="/llm/why-residual">残差的动机</a>给出 \\(h+f(h)\\)。本课不重画旁路。缺口是：沿深度把许多 \\(f\\) 加回去，\\(h\\) 的均值与范数会漂移；点积打分、激活的工作区都对尺度敏感。批归一化按批统计，对变长序列、对小 \\(B\\) 不稳定。方法是 LayerNorm：在每个位置的特征维上独立地标准化。本课只讲动机与接口，不把 RMSNorm、Pre-LN / Post-LN 的全部变体写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>残差把增量加回 \\(h\\)。若 \\(f\\) 的输出均值为正或范数大于 \\(1\\)，深度个加法之后 \\(\\|h\\|\\) 可以单调涨。softmax 与点积会饱和，学习率失去意义。初始化只能管起点。缺口是一个在每层（或每块）可重复的复位：不依赖批里其他样本，不依赖序列里其他位置，只看当前向量的 \\(d\\) 个坐标。</p><p>BatchNorm 用批内同一通道的统计量。语言模型的 \\(B\\) 可以很小，长度不同，填充位置会污染均值；推理时还要维护滑动平均。LayerNorm 的统计量来自单一样本的特征维，训练与推理一致。这是序列模型更常用它的原因，不是因为它「总是比 BatchNorm 准」。</p><p><span class="marginnote">初学者容易以为「归一化就是跨样本求平均」。BatchNorm 确实把一个通道在整批样本上求统计，像全班一起算平均分；LayerNorm 是每个位置在自己的 \\(d\\) 个特征里求统计，像每人只拿自己的各科成绩做标准化。批越小、序列越参差，前者的统计越抖，后者完全不受批的影响。</span></p><h3 id="layernorm-不是「把向量变成单位长度」这么一次" tabindex="-1">LayerNorm 不是「把向量变成单位长度」这么一次 <a class="header-anchor" href="#layernorm-不是「把向量变成单位长度」这么一次" aria-label="Permalink to &quot;LayerNorm 不是「把向量变成单位长度」这么一次&quot;">​</a></h3><p>减均值再除标准差之后，结果仍可再乘可学习的 \\(\\gamma\\)、加 \\(\\beta\\)。模型可以恢复尺度与偏移；归一化强迫的是<strong>内部</strong>先居中、先单位方差，再允许仿射。只除 \\(\\ell_2\\) 范数（不做减均值）是另一算子，后课 RMSNorm 走那条，本课不提前替换。也不要把 LayerNorm 当成损失上的约束：它是前向里的一层，有自己的反向。</p><p><span class="marginnote">对 \\(x\\in\\mathbb{R}^d\\)，\\(\\mu=\\frac{1}{d}\\sum_i x_i\\)，\\(\\sigma^2=\\frac{1}{d}\\sum_i(x_i-\\mu)^2\\)，\\(\\hat x_i=\\gamma_i\\frac{x_i-\\mu}{\\sqrt{\\sigma^2+\\varepsilon}}+\\beta_i\\)。\\(\\varepsilon\\) 防止除零。\\(\\gamma,\\beta\\) 与 \\(d\\) 同形，按位置广播。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入形状 \\((B,n,d)\\)，LN 在最后一维上算 \\(\\mu,\\sigma\\)，输出同形。放在残差块里有两种常见秩序：先 LN 再 \\(f\\) 再相加（Pre-LN），或先 \\(f\\) 再相加再 LN（Post-LN）。Pre-LN 让 \\(f\\) 吃到尺度稳定的输入，深层往往更好训；Post-LN 让块输出被重新标准化。本课不裁定唯一正确；后课读结构图时要看 LN 画在加号前还是后。</p>',12)),(o(),m(n,null,{default:e(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%BD%8D%E7%BD%AE%E4%B8%8A%E7%9A%84%E5%90%91%E9%87%8F%22%5D%20--%3E%20MU%5B%22%E5%87%8F%E7%89%B9%E5%BE%81%E5%9D%87%E5%80%BC%22%5D%0A%20%20MU%20--%3E%20SIG%5B%22%E9%99%A4%E7%89%B9%E5%BE%81%E6%A0%87%E5%87%86%E5%B7%AE%22%5D%0A%20%20SIG%20--%3E%20AFF%5B%22%E5%8F%AF%E5%AD%A6%E4%B9%A0%E7%9A%84%20gamma%20%E4%B8%8E%20beta%22%5D%0A%20%20AFF%20--%3E%20Y%5B%22%E5%B0%BA%E5%BA%A6%E5%A4%8D%E4%BD%8D%E5%90%8E%E7%9A%84%E5%90%91%E9%87%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,[r("span",{class:"marginnote"},"代个数：某位置向量 \\(x=(1,2,3)\\)，\\(d=3\\)。均值 \\(\\mu=2\\)，方差 \\(\\sigma^2=\\frac{(1-2)^2+0+(3-2)^2}{3}=\\frac{2}{3}\\)。减均值除标准差后得 \\(\\hat x\\approx(-1.22,\\,0,\\,1.22)\\)——均值归零、方差归一，但三个数的大小顺序没变。之后 \\(\\gamma,\\beta\\) 再把这个「标准形」拉伸、平移到网络喜欢的位置。")],-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"LN 把「绝对尺度」从残差流里拿走，留给 \\(\\gamma\\) 去学相对尺度。点积的输入不再随深度漂到几十，softmax 更不容易无故饱和。它也引入新的依赖：每个坐标的输出依赖该位置上所有坐标的统计量，反向会有对应的耦合。这通常可接受。LN 不能替代残差：没有加法旁路时，深层增益连乘仍在；LN 管的是每一步的工作点，不管路径拓扑。",-1)),(o(),m(n,null,{default:e(()=>[s(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%20h%22%5D%20--%3E%7C%22Pre-LN%22%7C%20P1%5B%22%E5%85%88%E5%BD%92%E4%B8%80%E5%8C%96%22%5D%0A%20%20P1%20--%3E%20P2%5B%22f%20%E5%90%83%E5%88%B0%E7%A8%B3%E5%AE%9A%E8%BE%93%E5%85%A5%22%5D%0A%20%20P2%20--%3E%20P3%5B%22%E5%8A%A0%20h%20%E8%BE%93%E5%87%BA%22%5D%0A%20%20X%20--%3E%7C%22Post-LN%22%7C%20Q1%5B%22%E5%85%88%E7%AE%97%20f%22%5D%0A%20%20Q1%20--%3E%20Q2%5B%22%E5%8A%A0%20h%22%5D%0A%20%20Q2%20--%3E%20Q3%5B%22%E6%9C%80%E5%90%8E%E5%BD%92%E4%B8%80%E5%8C%96%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>\\(\\varepsilon\\) 过小，某位置特征几乎常数时除零风险上升；过大则标准化变弱。这是数值地板，不是新的归纳偏置。LN 对每个位置独立，因此不能在位置之间传递「这一批有多亮」——那是 BatchNorm 的能力，也是它在小 \\(B\\) 上不稳的原因。序列模型用 LN，是在放弃跨样本统计，换取长度与批大小无关。</p><p><span class="marginnote">\\(\\varepsilon\\) 可以理解成「除法的保险丝」：分母 \\(\\sqrt{\\sigma^2+\\varepsilon}\\) 保证即使某位置的特征几乎全相等（\\(\\sigma^2\\approx0\\)），除法也不会爆炸。典型取值 \\(10^{-5}\\)，比正常方差小几个量级——平时不起作用，只在险情出现时兜底，并不改变归一化的本意。</span></p><p>与权重衰减的互动：\\(\\gamma,\\beta\\) 是否衰减会影响尺度自由度。常见做法是不衰减 LN 的仿射参数，与偏置类似。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 RMSNorm 的公式对照，不讨论跨设备的统计同步。下一课<a href="/llm/dropout-intuition">Dropout 直觉</a>是正则，不是归一化。后课默认：序列模型的块内用 LayerNorm 复位特征尺度；残差相加与 LN 的顺序要在结构里写明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>残差加法会累积尺度；LN 在每个位置的特征维上减均值除标准差。</li><li>统计量不依赖批，适合变长序列与小 \\(B\\)。</li><li>\\(\\gamma,\\beta\\) 允许恢复仿射；LN 不是死钉单位范数。</li><li>Pre-LN / Post-LN 改变 \\(f\\) 看见的尺度，需在图上标明。</li><li>出处：Ba, Kiros &amp; Hinton, 2016。</li></ul>',7))])}const D=E(B,[["render",h]]);export{c as __pageData,D as default};
